// Online commerce: never cache customer, payment, authentication or API data.
self.addEventListener('install',()=>self.skipWaiting());
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const name of await caches.keys())if(name.startsWith('racharla-preview-shell-'))await caches.delete(name);await self.clients.claim();})()));
self.addEventListener('fetch',event=>{if(event.request.mode==='navigate'&&new URL(event.request.url).origin===self.location.origin)event.respondWith(fetch(event.request).catch(()=>new Response('<!doctype html><html lang="en"><meta name="viewport" content="width=device-width"><title>Racharla Mart — Offline</title><h1>You are offline</h1><p>Reconnect to view products and orders or make payments.</p><a href="/connected.html">Try again</a></html>',{status:503,headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store'}})));});
